# Compute convex hull membership for demo 2 points and compare to added cells.
pts=[(10,3),(6,4),(11,4),(2,5),(7,5),(3,6),(8,6),(0,7),(4,7),(9,7),(1,8),(5,8),(10,8),(2,9),(6,9),(11,9),(3,10),(7,10),(4,11),(8,11),(5,12),(9,12),(6,13),(10,13),(7,14),(8,15)] # (c,r)? better define x=col,y=row? points above listed (col,row)
def hull(points):
    p=sorted(set(points))
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for x in p:
        while len(lo)>=2 and cross(lo[-2],lo[-1],x)<=0: lo.pop()
        lo.append(x)
    up=[]
    for x in reversed(p):
        while len(up)>=2 and cross(up[-2],up[-1],x)<=0: up.pop()
        up.append(x)
    return lo[:-1]+up[:-1]
h=hull(pts); h

def inside_hull(pt, poly):
    # boundary inclusive for convex polygon ccw
    return all((poly[(i+1)%len(poly)][0]-poly[i][0])*(pt[1]-poly[i][1])-(poly[(i+1)%len(poly)][1]-poly[i][1])*(pt[0]-poly[i][0]) >= 0 for i in range(len(poly)))
for r in range(16):
    print(r, [c for c in range(16) if inside_hull((c,r),h)])

